def elaborar_mensaje(nombre, tipo):
    if tipo == "pyme":
        return f"¡Hola *{nombre}*!\n\nDesde *Precios de Prepagas*, te acercamos propuestas de cobertura médica para particulares, familias y *PyMEs*.\nComercializamos *Sancor Salud* y *Prevención Salud*.\n\nSi sos PyME, podés armar tu grupo a partir de *5 personas*, que pueden ser empleados o familiares, con planes y tarifas especiales. También tenemos beneficios adicionales para grupos de más de 30 personas.\n\n¿Querés conocer las opciones? *Simplemente respondé a éste mensaje* para que podamos ayudarte a encontrar la mejor propuesta sin compromiso."
    return f"¡Hola *{nombre.strip().split()[0]}*!\n\nDesde *Precios de Prepagas*, te acercamos propuestas de cobertura médica pensadas para cuidar tu salud y la de tus seres queridos.\nComercializamos *Sancor Salud* y *Prevención Salud*.\n\nPodés elegir *planes y tarifas especiales para vos y tu familia*. También tenemos beneficios adicionales para *PyMEs*.\n\n¿Querés conocer las opciones? *Simplemente respondé a éste mensaje* para que podamos ayudarte a encontrar la mejor propuesta sin compromiso."
